create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key default gen_random_uuid(),owner_id uuid,name text not null,age int,weight_kg numeric,target_calories numeric,target_protein numeric,target_fat numeric,target_carbs numeric,target_fiber numeric,max_sugar numeric,updated_at timestamptz default now());
create table if not exists foods(id uuid primary key default gen_random_uuid(),owner_id uuid,name text not null,brand text,calories_100 numeric default 0,protein_100 numeric default 0,fat_100 numeric default 0,carbs_100 numeric default 0,fiber_100 numeric default 0,sugar_100 numeric default 0,is_public boolean default false,updated_at timestamptz default now());
create table if not exists recipes(id uuid primary key default gen_random_uuid(),owner_id uuid,name text not null,total_portions numeric default 1,updated_at timestamptz default now());
create table if not exists recipe_items(id uuid primary key default gen_random_uuid(),recipe_id uuid references recipes(id) on delete cascade,food_id uuid references foods(id),quantity_g numeric not null);
create table if not exists meal_entries(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,eaten_on date not null,meal_name text not null,item_name text not null,calories numeric default 0,protein numeric default 0,fat numeric default 0,carbs numeric default 0,fiber numeric default 0,sugar numeric default 0,created_at timestamptz default now());
create table if not exists weight_logs(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,measured_on date not null,weight_kg numeric not null,unique(profile_id,measured_on));
alter table profiles enable row level security; alter table foods enable row level security; alter table recipes enable row level security; alter table recipe_items enable row level security; alter table meal_entries enable row level security; alter table weight_logs enable row level security;
create policy "profiles_owner" on profiles for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "foods_read" on foods for select using(owner_id=auth.uid() or is_public=true); create policy "foods_write" on foods for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "recipes_owner" on recipes for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "recipe_items_owner" on recipe_items for all using(exists(select 1 from recipes r where r.id=recipe_id and r.owner_id=auth.uid())) with check(exists(select 1 from recipes r where r.id=recipe_id and r.owner_id=auth.uid()));
create policy "meals_owner" on meal_entries for all using(exists(select 1 from profiles p where p.id=profile_id and p.owner_id=auth.uid())) with check(exists(select 1 from profiles p where p.id=profile_id and p.owner_id=auth.uid()));
create policy "weights_owner" on weight_logs for all using(exists(select 1 from profiles p where p.id=profile_id and p.owner_id=auth.uid())) with check(exists(select 1 from profiles p where p.id=profile_id and p.owner_id=auth.uid()));
